import json

with open('/Users/tajun/spJavis/AgenticWorkflow-main-stock-filtering-collector/.claude/settings.json') as f:
    config = json.load(f)

hooks = config.get('hooks', {})

# Check for hooks that might write state.yaml concurrently
print("=== CONCURRENT HOOK ANALYSIS ===\n")

for hook_type, hook_list in hooks.items():
    print(f"Hook Type: {hook_type}")
    if isinstance(hook_list, list):
        for idx, hook_obj in enumerate(hook_list):
            if isinstance(hook_obj, dict) and 'hooks' in hook_obj:
                matcher = hook_obj.get('matcher', '(no matcher)')
                print(f"  [{idx}] Matcher: {matcher}")
                for hook in hook_obj['hooks']:
                    cmd = hook.get('command', '')
                    if 'state.yaml' in cmd:
                        print(f"      --> References state.yaml: {cmd[:80]}...")
                    script = cmd.split('/')[-1].split()[0] if cmd else ''
                    if script:
                        print(f"      Script: {script}")
    print()

# Check for overlapping matchers that could cause race conditions
print("\n=== OVERLAPPING MATCHERS (Potential Race Conditions) ===\n")

posttool_matchers = []
for hook_obj in hooks.get('PostToolUse', []):
    matcher = hook_obj.get('matcher', '')
    if matcher:
        matchers = [m.strip() for m in matcher.split('|')]
        posttool_matchers.append((matcher, hook_obj))

# Find overlaps
